namespace MyApp.Evals.Tests;

/// <summary>
/// Resolves the same IChatClient the app uses, by building a minimal
/// host that mirrors the app's DI registration.
/// Detected: AddAzureOpenAIChatClient("chat", "gpt-4o-mini") at AppHost.cs:2
/// </summary>
internal static class AgentChatClientFactory
{
    public static IChatClient Create()
    {
        var builder = Host.CreateApplicationBuilder();

        // In test hosts, the entry assembly is testhost.exe so user-secrets
        // are NOT auto-loaded. Add them explicitly from THIS assembly.
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

        builder.AddAzureOpenAIChatClient("chat");
        var host = builder.Build();
        try
        {
            return host.Services.GetRequiredService<IChatClient>();
        }
        catch (InvalidOperationException ex)
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but IChatClient could not be resolved. " +
                "The detected registration reads connection string \"chat\" from configuration. " +
                "Aspire's AppHost populates this at runtime, but `dotnet test` runs standalone.\n" +
                "Wire one of:\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" " +
                "--project MyApp.Evals.Tests\n" +
                "Note: the hostname strips dashes from the resource name.",
                ex);
        }
    }
}

namespace MyApp.Evals.Tests;

/// <summary>
/// Stub chat client used when EVAL_USE_REAL_AGENT is unset.
/// Returns a deterministic response so NLP evaluators can produce real metrics.
/// </summary>
internal sealed class StubChatClient : IChatClient
{
    public Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        var userMsg = messages.LastOrDefault(m => m.Role == ChatRole.User)?.Text ?? "";
        var reply = $"This is a stub response to: {userMsg}. " +
                    "The agent would provide a real answer when EVAL_USE_REAL_AGENT=1 is set.";
        return Task.FromResult(new ChatResponse(new ChatMessage(ChatRole.Assistant, reply))
        {
            ModelId = "stub",
            Usage = new UsageContent { InputTokenCount = userMsg.Length / 4, OutputTokenCount = reply.Length / 4 }
        });
    }

    public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default) =>
        throw new NotSupportedException("Streaming not supported in stub mode.");

    public object? GetService(Type serviceType, object? serviceKey = null) => null;
    public void Dispose() { }
}

namespace MyApp.Evals.Tests;

/// <summary>
/// Wiring helpers for resolving agent and judge IChatClient instances.
/// </summary>
internal static class Wire
{
    public static IChatClient ResolveAgentClient() =>
        EvalEnv.UseRealAgent ? AgentChatClientFactory.Create() : new StubChatClient();

    public static IChatClient ResolveJudgeClient(IChatClient agentClient)
    {
        var judgeDeployment = Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME");
        if (!string.IsNullOrEmpty(judgeDeployment))
        {
            // Separate judge deployment — build a dedicated client.
            var builder = Host.CreateApplicationBuilder();
            builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);
            builder.AddAzureOpenAIChatClient(judgeDeployment);
            return builder.Build().Services.GetRequiredService<IChatClient>();
        }

        // Default: same client for both agent and judge (saves creds setup + cache reuse).
        return agentClient;
    }
}

using System.Diagnostics;
using System.Text.Json;

namespace MyApp.Evals.Tests;

[TestClass]
public sealed class TelemetryTests
{
    public static IEnumerable<object[]> Inputs() =>
        InputsLoader.Load().Select(i => new object[] { i });

    [TestMethod, DynamicData(nameof(Inputs), DynamicDataSourceType.Method)]
    public async Task Capture(TelemetryInput input)
    {
        var inner = Wire.ResolveAgentClient();
        var wrapped = new TelemetryCapturingChatClient(inner, PriceTable.Load());

        var messages = new List<ChatMessage> { new(ChatRole.User, input.Text) };
        var sw = Stopwatch.StartNew();
        var response = await wrapped.GetResponseAsync(messages);
        sw.Stop();

        TelemetryStore.Record(new TelemetryRecord(
            AgentName: input.Agent,
            Model: response.ModelId ?? "unknown",
            InputTokens: response.Usage?.InputTokenCount ?? 0,
            OutputTokens: response.Usage?.OutputTokenCount ?? 0,
            LatencyMs: sw.ElapsedMilliseconds,
            CostUsd: wrapped.LastCostUsd));
    }

    [ClassCleanup]
    public static void WriteReports() => TelemetryStore.FlushTo(
        Path.Combine(RepoRoot.Find(), ".copilot", "perf-reports", "evals",
                     EvalEnv.ReportFolder));
}

public record TelemetryInput(string Agent, string Text);

public record TelemetryRecord(
    string AgentName, string Model, int InputTokens,
    int OutputTokens, long LatencyMs, decimal CostUsd);

internal static class InputsLoader
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    public static List<TelemetryInput> Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Telemetry", "inputs.json");
        return JsonSerializer.Deserialize<List<TelemetryInput>>(
            File.ReadAllText(path), s_options) ?? [];
    }
}

internal static class PriceTable
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    public static Dictionary<string, PriceEntry> Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Telemetry", "prices.json");
        return JsonSerializer.Deserialize<Dictionary<string, PriceEntry>>(
            File.ReadAllText(path), s_options) ?? [];
    }

    public static decimal Cost(Dictionary<string, PriceEntry> table, string? model, int input, int output)
    {
        if (model is null || !table.TryGetValue(model, out var entry)) return 0;
        return (input / 1000m * entry.InputPer1k) + (output / 1000m * entry.OutputPer1k);
    }
}

public record PriceEntry(decimal InputPer1k, decimal OutputPer1k);

internal sealed class TelemetryCapturingChatClient(IChatClient inner, Dictionary<string, PriceEntry> prices) : IChatClient
{
    public decimal LastCostUsd { get; private set; }

    public async Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages, ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        var resp = await inner.GetResponseAsync(messages, options, cancellationToken);
        var usage = resp.Usage;
        LastCostUsd = PriceTable.Cost(prices, resp.ModelId,
            usage?.InputTokenCount ?? 0, usage?.OutputTokenCount ?? 0);
        return resp;
    }

    public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages, ChatOptions? options = null,
        CancellationToken cancellationToken = default) =>
        inner.GetStreamingResponseAsync(messages, options, cancellationToken);

    public object? GetService(Type serviceType, object? serviceKey = null) =>
        inner.GetService(serviceType, serviceKey);

    public void Dispose() => inner.Dispose();
}

internal static class TelemetryStore
{
    private static readonly List<TelemetryRecord> s_records = [];

    public static void Record(TelemetryRecord r) { lock (s_records) s_records.Add(r); }

    public static void FlushTo(string outDir)
    {
        Directory.CreateDirectory(outDir);
        List<TelemetryRecord> snapshot;
        lock (s_records) { snapshot = [.. s_records]; s_records.Clear(); }

        var json = JsonSerializer.Serialize(snapshot, new JsonSerializerOptions { WriteIndented = true });
        File.WriteAllText(Path.Combine(outDir, "telemetry.json"), json);

        var md = "| Agent | Model | Input Tokens | Output Tokens | Latency (ms) | Cost (USD) |\n" +
                 "|-------|-------|-------------|--------------|-------------|------------|\n" +
                 string.Join("\n", snapshot.Select(r =>
                     $"| {r.AgentName} | {r.Model} | {r.InputTokens} | {r.OutputTokens} | {r.LatencyMs} | {r.CostUsd:F6} |"));
        File.WriteAllText(Path.Combine(outDir, "telemetry.md"), md);
    }
}

